## `w9_laws.patch` — the complete reviewable W9 delta (laws F-C4-578…586 + the W9 probe)

1015 lines, sha16 `b708b8460eac637c`, `git apply` (no flags) on a **main(S168) + w8_laws applied** tree (verified CLEAN this session). Every hunk carries its live root + upstream citation in comments.

```diff
diff --git a/miniandroid/src/dex/dalvik_engine.cpp b/miniandroid/src/dex/dalvik_engine.cpp
index 379f18f..175daf2 100755
--- a/miniandroid/src/dex/dalvik_engine.cpp
+++ b/miniandroid/src/dex/dalvik_engine.cpp
@@ -8022,6 +8022,65 @@ bool DalvikExecutionEngine::try_recursive_invoke(
             }
         }
     }
+    // ────────────────────────────────────────────────────────────────────────
+    // W9 (Coder-4) ROOM/ISINSTANCE PROBE — env-gated
+    // MINIANDROID_W9_PROBE, bounded, zero behavior change. The frontier
+    // families this wave: (a) Room's validateTypeConverters chain (the
+    // generated required-converters map walk: RoomDatabaseKt__,
+    // RoomDatabase$Builder, DatabaseConfiguration, the generated
+    // *_Impl database class) and (b) the KClass/ClassReference
+    // reflection family that feeds Class.isInstance (Kotlin's
+    // ClassReference + JvmClassMappingKt). Trace shape mirrors the W8
+    // probe (class.method + arg kinds/oids/strings + caller).
+    // ────────────────────────────────────────────────────────────────────────
+    {
+        static thread_local const bool w9p_on =
+            std::getenv("MINIANDROID_W9_PROBE") != nullptr;
+        if (w9p_on) {
+            const bool w9_room =
+                declaring_class.find("RoomDatabase") != std::string::npos ||
+                declaring_class.find("DatabaseConfiguration") !=
+                    std::string::npos ||
+                declaring_class.find("DatabaseModule") != std::string::npos ||
+                (declaring_class.find("typeConverter") !=
+                     std::string::npos &&
+                 method_name == "<init>");
+            const bool w9_kclass =
+                declaring_class.find("ClassReference") != std::string::npos ||
+                declaring_class.find("JvmClassMapping") != std::string::npos ||
+                declaring_class.find("KClassUtil") != std::string::npos;
+            if (w9_room || w9_kclass) {
+                static thread_local uint64_t w9p_n = 0;
+                if (w9p_n < 600) {
+                    ++w9p_n;
+                    std::cerr << "[W9-PROBE] " << declaring_class << "."
+                              << method_name << " argc=" << args.size();
+                    for (size_t wi = 0; wi < args.size() && wi < 4; ++wi) {
+                        const DalvikValue& wa = args[wi];
+                        std::cerr << " a" << wi << "=";
+                        if (wa.is_null)
+                            std::cerr << "null";
+                        else if (wa.type == DalvikType::OBJECT_REF)
+                            std::cerr << "o" << wa.object_id
+                                      << (wa.class_desc.empty()
+                                              ? std::string("")
+                                              : "/" + wa.class_desc);
+                        else if (wa.type == DalvikType::STRING_REF)
+                            std::cerr << "\"" <<
+                                wa.string_val.substr(0, 48) << "\"";
+                        else if (wa.type == DalvikType::INT32)
+                            std::cerr << wa.int_val;
+                        else if (wa.type == DalvikType::INT64)
+                            std::cerr << "L" << (long long)wa.long_val;
+                        else
+                            std::cerr << "t" << (int)wa.type;
+                    }
+                    std::cerr << " caller=" << current_class_ << "."
+                              << current_method_ << std::endl;
+                }
+            }
+        }
+    }
     // F-NEW-267 (CONT-64 W1) COMPOSE-MEASURE TRACE — env-gated
     // MINIANDROID_COMPOSE_MEASURE_TRACE=1, bounded. Every entry of the
     // compose measure/layout delegate entry points (the R8 names decoded on
@@ -33068,6 +33127,504 @@ bool DalvikExecutionEngine::bridge_to_api(const std::string& class_name,
             return true;
         }
     }
+    // ────────────────────────────────────────────────────────────────────
+    // F-C4-582 (W9): SSLContext OBJECT-SHAPE law. ROOT (live, TB v24):
+    // DefaultTrustedSocketFactory.<clinit> pc=63 called
+    // SSLContext.getInstance("TLS").init(...) — SSLContext had NO bridge
+    // arm, getInstance answered the typed-null default → the null
+    // receiver NPE 'SSLContext.init on a null object reference' (caught
+    // by the clinit's catch, the whole trusted-socket factory then
+    // shadow-null for the mail engine). AOSP law (javax.net.ssl
+    // SSLContext.java): getInstance(String) NEVER answers null (unknown
+    // protocol → NoSuchAlgorithmException); init(KM[], TM[], SR) is the
+    // configuration step (no-op in this runtime — the socket layer is the
+    // S100 NET-001 TLS bridge); getSocketFactory/getServerSocketFactory
+    // answer SSLSocketFactory objects; getDefault answers the default
+    // context. Same never-null object-shape discipline as F516-L3.
+    // ────────────────────────────────────────────────────────────────────
+    if (class_name == "Ljavax/net/ssl/SSLContext;") {
+        if (method == "getInstance" && !args.empty() &&
+            args[0].type == DalvikType::STRING_REF) {
+            const std::string proto = args[0].string_val;
+            if (proto != "TLS" && proto != "SSL" && proto != "Default" &&
+                proto != "TLSv1" && proto != "TLSv1.1" && proto != "TLSv1.2" &&
+                proto != "TLSv1.3") {
+                throw_deferred("Ljava/security/NoSuchAlgorithmException;",
+                    "SSLContext " + proto + " not available", "F-C4-582");
+                result = DalvikValue::make_null();
+                status = ApiCallTrace::Status::IMPLEMENTED;
+                return true;
+            }
+            uint32_t oid = heap_.allocate("Ljavax/net/ssl/SSLContext;", pc_,
+                call_stack_.empty() ? 0 : call_stack_.top().frame_id);
+            heap_.set_object_field(oid, "__protocol__",
+                DalvikValue::make_string(proto, 0));
+            static thread_local uint64_t f582_n = 0;
+            if (f582_n < 8) { ++f582_n;
+                std::cerr << "[F-C4-582] SSLContext.getInstance('" << proto
+                          << "') -> oid=" << oid << " (never-null law)"
+                          << std::endl; }
+            result = DalvikValue::make_object(oid, "Ljavax/net/ssl/SSLContext;");
+            status = ApiCallTrace::Status::IMPLEMENTED;
+            return true;
+        }
+        if (method == "getDefault") {
+            uint32_t oid = heap_.allocate("Ljavax/net/ssl/SSLContext;", pc_,
+                call_stack_.empty() ? 0 : call_stack_.top().frame_id);
+            heap_.set_object_field(oid, "__protocol__",
+                DalvikValue::make_string("Default", 0));
+            result = DalvikValue::make_object(oid, "Ljavax/net/ssl/SSLContext;");
+            status = ApiCallTrace::Status::IMPLEMENTED;
+            return true;
+        }
+        if (method == "init") {
+            result = DalvikValue::make_void();
+            status = ApiCallTrace::Status::IMPLEMENTED;
+            return true;
+        }
+        if (method == "getProtocol" && !args.empty() &&
+            args[0].type == DalvikType::OBJECT_REF) {
+            auto pv = heap_.get_object_field(args[0].object_id, "__protocol__");
+            result = pv.has_value() ? *pv : DalvikValue::make_string("TLS", 0);
+            status = ApiCallTrace::Status::IMPLEMENTED;
+            return true;
+        }
+        if (method == "getSocketFactory" || method == "getServerSocketFactory") {
+            uint32_t sf = heap_.allocate(
+                "Ljavax/net/ssl/SSLSocketFactory;", pc_,
+                call_stack_.empty() ? 0 : call_stack_.top().frame_id);
+            result = DalvikValue::make_object(sf, "Ljavax/net/ssl/SSLSocketFactory;");
+            status = ApiCallTrace::Status::IMPLEMENTED;
+            return true;
+        }
+        if (method == "createSSLEngine") {
+            uint32_t se = heap_.allocate(
+                "Ljavax/net/ssl/SSLEngine;", pc_,
+                call_stack_.empty() ? 0 : call_stack_.top().frame_id);
+            result = DalvikValue::make_object(se, "Ljavax/net/ssl/SSLEngine;");
+            status = ApiCallTrace::Status::IMPLEMENTED;
+            return true;
+        }
+    }
+    // ────────────────────────────────────────────────────────────────────
+    // F-C4-584 (W9): Arrays.stream + Stream EAGER-PIPELINE + Optional
+    // protocol. ROOT (live, NC v35.0.2, post-583 census): NC's
+    // UserAccountManagerImpl.getCurrentAccount (pc=0x18..0x21) does
+    // `Arrays.stream(accounts).filter(pred).findFirst().orElse(null)`
+    // — Arrays.stream had NO arm → null Stream → `Stream.filter on a
+    // null object reference` NPE inside getUser() → the SAME 20+ row
+    // NC Dagger family (ConnectivityKey.getBy → ConnectivityServiceImpl
+    // ctor → injectMainApp). OpenJDK laws implemented:
+    //   · Arrays.stream(T[]) → a Stream OVER THE ARRAY'S ELEMENTS
+    //     (java.util.Arrays#stream — sequential, ordered);
+    //   · Stream.filter(Predicate) → a Stream OF THE PASSING ELEMENTS —
+    //     evaluation is EAGER here (the engine's streams are always
+    //     finite, materialized collections; the observable result of
+    //     filter+findFirst is identical to the lazy pipeline);
+    //     the predicate is the DESUGARED-LAMBDA DEX object — its
+    //     test(Object) method runs via recursive invoke (F-C4-564
+    //     discipline), so app filter logic is REAL bytecode;
+    //   · Stream.findFirst() → Optional of the first element, or
+    //     Optional.empty (OpenJDK findFirst on an empty stream);
+    //   · Optional.of/ofNullable/empty/isPresent/isEmpty/get/orElse —
+    //     the full OpenJDK value-container protocol (getUser path uses
+    //     ofNullable + orElse).
+    // ────────────────────────────────────────────────────────────────────
+    if (class_name == "Ljava/util/Arrays;" && method == "stream" &&
+        !args.empty() && args[0].type == DalvikType::OBJECT_REF &&
+        args[0].object_id != 0 && heap_.has_object(args[0].object_id)) {
+        const uint32_t src_arr = args[0].object_id;
+        auto lenv = heap_.get_object_field(src_arr, "__array_length__");
+        const int n = (lenv.has_value() && lenv->type == DalvikType::INT32)
+                          ? lenv->int_val : 0;
+        uint32_t sid = heap_.allocate("Ljava/util/stream/Stream;", pc_,
+            call_stack_.empty() ? 0 : call_stack_.top().frame_id);
+        for (int i = 0; i < n && i < 4096; ++i) {
+            auto ev = heap_.get_object_field(
+                src_arr, "array[" + std::to_string(i) + "]");
+            heap_.set_object_field(
+                sid, "__el" + std::to_string(i) + "__",
+                ev.value_or(DalvikValue::make_null()));
+        }
+        heap_.set_object_field(sid, "__eln__", DalvikValue::make_int(
+            n < 4096 ? n : 4096));
+        static thread_local uint64_t f584_s = 0;
+        if (f584_s < 8) { ++f584_s;
+            std::cerr << "[F-C4-584] Arrays.stream(array len=" << n
+                      << ") -> stream o" << sid << std::endl; }
+        result = DalvikValue::make_object(sid, "Ljava/util/stream/Stream;");
+        status = ApiCallTrace::Status::IMPLEMENTED;
+        return true;
+    }
+    if (class_name == "Ljava/util/stream/Stream;" &&
+        !args.empty() && args[0].type == DalvikType::OBJECT_REF &&
+        args[0].object_id != 0 && heap_.has_object(args[0].object_id)) {
+        const uint32_t s = args[0].object_id;
+        auto rd_n = [&](uint32_t oid) -> int {
+            auto v = heap_.get_object_field(oid, "__eln__");
+            return (v.has_value() && v->type == DalvikType::INT32)
+                       ? v->int_val : 0;
+        };
+        auto rd_el = [&](uint32_t oid, int i) {
+            return heap_.get_object_field(
+                oid, "__el" + std::to_string(i) + "__");
+        };
+        if (method == "filter" && args.size() >= 2 &&
+            args[1].type == DalvikType::OBJECT_REF &&
+            args[1].object_id != 0 && heap_.has_object(args[1].object_id)) {
+            const uint32_t pred = args[1].object_id;
+            auto* pred_obj = heap_.get(pred);
+            const std::string pred_cls =
+                pred_obj ? std::string(pred_obj->class_descriptor)
+                         : std::string();
+            const int n = rd_n(s);
+            uint32_t out = heap_.allocate("Ljava/util/stream/Stream;", pc_,
+                call_stack_.empty() ? 0 : call_stack_.top().frame_id);
+            int kept = 0;
+            for (int i = 0; i < n; ++i) {
+                auto ev = rd_el(s, i);
+                if (!ev.has_value()) continue;
+                bool pass = false;
+                if (!pred_cls.empty()) {
+                    DalvikValue rv; DalvikExecutionResult res;
+                    std::vector<DalvikValue> targs;
+                    targs.push_back(DalvikValue::make_object(
+                        pred, pred_cls));
+                    targs.push_back(*ev);
+                    bool ok = try_recursive_invoke(
+                        pred_cls, "test", targs, rv, res,
+                        "(Ljava/lang/Object;)Z");
+                    if (!ok)
+                        ok = try_recursive_invoke_on_super(
+                            pred_cls, "test", targs, rv, res,
+                            "(Ljava/lang/Object;)Z");
+                    if (ok && (rv.type == DalvikType::INT32 ||
+                               rv.type == DalvikType::BOOLEAN))
+                        pass = (rv.type == DalvikType::INT32)
+                                   ? (rv.int_val != 0) : rv.bool_val;
+                }
+                if (pass) {
+                    heap_.set_object_field(
+                        out, "__el" + std::to_string(kept) + "__", *ev);
+                    ++kept;
+                }
+            }
+            heap_.set_object_field(out, "__eln__",
+                                   DalvikValue::make_int(kept));
+            static thread_local uint64_t f584_f = 0;
+            if (f584_f < 8) { ++f584_f;
+                std::cerr << "[F-C4-584] Stream.filter(" << pred_cls
+                          << ") over " << n << " -> kept " << kept
+                          << std::endl; }
+            result = DalvikValue::make_object(
+                out, "Ljava/util/stream/Stream;");
+            status = ApiCallTrace::Status::IMPLEMENTED;
+            return true;
+        }
+        if (method == "findFirst") {
+            const int n = rd_n(s);
+            uint32_t opt = heap_.allocate("Ljava/util/Optional;", pc_,
+                call_stack_.empty() ? 0 : call_stack_.top().frame_id);
+            if (n > 0) {
+                auto ev = rd_el(s, 0);
+                heap_.set_object_field(opt, "__present__",
+                    DalvikValue::make_int(1));
+                heap_.set_object_field(opt, "__value__",
+                    ev.value_or(DalvikValue::make_null()));
+            } else {
+                heap_.set_object_field(opt, "__present__",
+                    DalvikValue::make_int(0));
+            }
+            result = DalvikValue::make_object(opt, "Ljava/util/Optional;");
+            status = ApiCallTrace::Status::IMPLEMENTED;
+            return true;
+        }
+        if (method == "count") {
+            result = DalvikValue::make_long(static_cast<int64_t>(rd_n(s)));
+            status = ApiCallTrace::Status::IMPLEMENTED;
+            return true;
+        }
+    }
+    // ────────────────────────────────────────────────────────────────────
+    // F-C4-585 (W9): android.accounts.Account CONSTRUCTOR + FIELD law.
+    // ROOT (live, NC v35.0.2, post-584 census): with zero device accounts
+    // NC's getCurrentAccount() (pc=0x52) falls back to its OWN
+    // getAnonymousAccount() which constructs `new Account(name, type)`
+    // from string resources; Account had NO constructor arm — the heap
+    // object was allocated with BOTH public fields unset →
+    // AccountExtensionsKt.isAnonymous pc=0x12 `account.type.equals(...)`
+    // → 'String.equals on a null object reference' NPE → the whole
+    // createUserFromAccount → getUser → ConnectivityKey.getBy chain.
+    // AOSP law (android.accounts.Account.java): `public Account(String
+    // name, String type)` stores BOTH as public final fields; equals/
+    // hashCode/toString are the name+type pair. getAnonymousAccount's
+    // type string and isAnonymous's compare string come from the SAME
+    // resource id, so the round-trip answers TRUE and NC's anonymous
+    // fallback path completes exactly as on a fresh install on hardware.
+    // ────────────────────────────────────────────────────────────────────
+    if (class_name == "Landroid/accounts/Account;" &&
+        method == "<init>" && args.size() >= 3) {
+        if (args[0].type == DalvikType::OBJECT_REF &&
+            args[0].object_id != 0 && heap_.has_object(args[0].object_id)) {
+            const uint32_t acc = args[0].object_id;
+            heap_.set_object_field(acc, "name",
+                args[1].type == DalvikType::STRING_REF
+                    ? args[1]
+                    : DalvikValue::make_null());
+            heap_.set_object_field(acc, "type",
+                args[2].type == DalvikType::STRING_REF
+                    ? args[2]
+                    : DalvikValue::make_null());
+            static thread_local uint64_t f585_n = 0;
+            if (f585_n < 8) { ++f585_n;
+                std::cerr << "[F-C4-585] Account.<init>(name='"
+                          << (args[1].type == DalvikType::STRING_REF
+                                  ? args[1].string_val.substr(0, 32)
+                                  : std::string("?"))
+                          << "', type='"
+                          << (args[2].type == DalvikType::STRING_REF
+                                  ? args[2].string_val.substr(0, 32)
+                                  : std::string("?"))
+                          << "') stored (public-fields law)" << std::endl; }
+        }
+        result = DalvikValue::make_void();
+        status = ApiCallTrace::Status::IMPLEMENTED;
+        return true;
+    }
+    if (class_name == "Landroid/accounts/Account;" &&
+        (method == "getName" || method == "getType") &&
+        !args.empty() && args[0].type == DalvikType::OBJECT_REF &&
+        args[0].object_id != 0 && heap_.has_object(args[0].object_id)) {
+        auto fv = heap_.get_object_field(
+            args[0].object_id, method == "getName" ? "name" : "type");
+        result = fv.value_or(DalvikValue::make_null());
+        status = ApiCallTrace::Status::IMPLEMENTED;
+        return true;
+    }
+    if (class_name == "Landroid/accounts/Account;" &&
+        method == "toString" && !args.empty() &&
+        args[0].type == DalvikType::OBJECT_REF &&
+        args[0].object_id != 0 && heap_.has_object(args[0].object_id)) {
+        auto nm = heap_.get_object_field(args[0].object_id, "name");
+        auto tp = heap_.get_object_field(args[0].object_id, "type");
+        std::string n = (nm.has_value() &&
+                         nm->type == DalvikType::STRING_REF)
+                            ? std::string(nm->string_val) : std::string();
+        std::string t = (tp.has_value() &&
+                         tp->type == DalvikType::STRING_REF)
+                            ? std::string(tp->string_val) : std::string();
+        // AOSP: Account#toString = "Account {name=" + name + ", type=" +
+        // type + "}"
+        result = DalvikValue::make_string(
+            "Account {name=" + n + ", type=" + t + "}", 0);
+        status = ApiCallTrace::Status::IMPLEMENTED;
+        return true;
+    }
+    // ────────────────────────────────────────────────────────────────────
+    // F-C4-586 (W9): java.net.URI MINIMAL OBJECT law. ROOT (live, NC
+    // v35.0.2, post-585 census): AnonymousUser.<init>(String) pc=0x12
+    // calls `URI.create("")` (the anonymous user's Server anchor) —
+    // java.net.URI had ZERO coverage, create() answered the typed-null
+    // default → the Server construction chain died and the NC
+    // ConnectivityService family (17 rows) stayed frozen. OpenJDK law
+    // (java.net.URI): create(String) NEVER answers null for a legal
+    // URI — "" IS legal (empty path, no scheme/host); toString() is the
+    // original spelling; getScheme/getHost/getPort/getPath answer the
+    // parsed components (null when absent, OpenJDK contract). Minimal
+    // faithful model: the raw string is the object's identity;
+    // components parsed with the generic RFC3986
+    // scheme://[userinfo@]host[:port]/path split.
+    // ────────────────────────────────────────────────────────────────────
+    if (class_name == "Ljava/net/URI;" &&
+        (method == "create" || method == "URI(") && !args.empty() &&
+        args[0].type == DalvikType::STRING_REF) {
+        uint32_t uid = heap_.allocate("Ljava/net/URI;", pc_,
+            call_stack_.empty() ? 0 : call_stack_.top().frame_id);
+        heap_.set_object_field(uid, "__uri__", args[0]);
+        static thread_local uint64_t f586_n = 0;
+        if (f586_n < 8) { ++f586_n;
+            std::cerr << "[F-C4-586] URI.create(\""
+                      << args[0].string_val.substr(0, 48)
+                      << "\") -> o" << uid << " (never-null law)"
+                      << std::endl; }
+        result = DalvikValue::make_object(uid, "Ljava/net/URI;");
+        status = ApiCallTrace::Status::IMPLEMENTED;
+        return true;
+    }
+    if (class_name == "Ljava/net/URI;" && !args.empty() &&
+        args[0].type == DalvikType::OBJECT_REF &&
+        args[0].object_id != 0 && heap_.has_object(args[0].object_id)) {
+        const uint32_t uid = args[0].object_id;
+        // F-C4-586: the `new URI(String)` constructor arm — the receiver
+        // was minted by new-instance; store the spelling on it.
+        if (method == "<init>" && args.size() >= 2 &&
+            args[1].type == DalvikType::STRING_REF) {
+            heap_.set_object_field(uid, "__uri__", args[1]);
+            result = DalvikValue::make_void();
+            status = ApiCallTrace::Status::IMPLEMENTED;
+            return true;
+        }
+        auto uri_str = [&]() -> std::string {
+            auto v = heap_.get_object_field(uid, "__uri__");
+            return (v.has_value() && v->type == DalvikType::STRING_REF)
+                       ? std::string(v->string_val) : std::string();
+        };
+        if (method == "toString" || method == "toASCIIString") {
+            result = DalvikValue::make_string(uri_str(), 0);
+            status = ApiCallTrace::Status::IMPLEMENTED;
+            return true;
+        }
+        if (method == "getScheme" || method == "getHost" ||
+            method == "getPath" || method == "getPort" ||
+            method == "getUserInfo" || method == "getAuthority" ||
+            method == "getFragment" || method == "getQuery") {
+            const std::string u = uri_str();
+            // generic split: scheme://[userinfo@]host[:port]/path[?q][#f]
+            std::string rest = u;
+            std::string scheme;
+            auto sp = rest.find("://");
+            if (sp != std::string::npos) {
+                scheme = rest.substr(0, sp);
+                rest = rest.substr(sp + 3);
+            }
+            std::string query, frag;
+            auto hpos = rest.find('#');
+            if (hpos != std::string::npos) {
+                frag = rest.substr(hpos + 1);
+                rest = rest.substr(0, hpos);
+            }
+            auto qpos = rest.find('?');
+            if (qpos != std::string::npos) {
+                query = rest.substr(qpos + 1);
+                rest = rest.substr(0, qpos);
+            }
+            std::string authority = rest;
+            std::string path;
+            auto ppos = rest.find('/');
+            if (ppos != std::string::npos) {
+                authority = rest.substr(0, ppos);
+                path = rest.substr(ppos);
+            }
+            std::string userinfo, hostport = authority;
+            auto upos = authority.find('@');
+            if (upos != std::string::npos) {
+                userinfo = authority.substr(0, upos);
+                hostport = authority.substr(upos + 1);
+            }
+            std::string host = hostport;
+            int port = -1;
+            auto cpos = hostport.rfind(':');
+            if (cpos != std::string::npos &&
+                hostport.find(']') == std::string::npos) {
+                host = hostport.substr(0, cpos);
+                try { port = std::stoi(hostport.substr(cpos + 1)); }
